/**
 * A Hard Message
 * --------------
 * Eli makes Samuel tell the whole message: the house of Eli will be judged, and no sacrifice can stop it. Stage: a chamber at first light, a boy trembling, an old man listening, a lamp going out; a prophecy delivered with tears.
 *
 * Palette 0x1a2a1a → 0x060402 · light: ember · hero: house
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./samuel-kit.js.
 */

import { THREE, createScene, house, person } from './samuel-kit.js';

const BG = 0x1a2a1a;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 352939329, bg: BG, fogNear: 45, fogFar: 180 });

    /* light — ember */
    W.lights({ sky: 0x3a2418, gnd: 0x1a0e08, hemi: 0.4, sun: 0xff7a30, sunI: 0.7, sunPos: [20, 26, 30] });

    W.stars(90, 150, [0xf0e0c8, 0xd8c0a0], 0.7);
    W.disc([0, 34, -150], 14, 0xff8a30, 0.12);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* house: mud-brick walls, flat roof, door */
    house(W, group, 11, 0, -16, 1.0 + W.r() * 0.3, { mud: 0x060402 });
    house(W, group, 21, 0, -9, 0.8 + W.r() * 0.3, { mud: 0x060402 });

    /* hero: the house */
    house(W, group, 0, 0, -2, 1.3, { mud: 0x060402 });

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x8a6a44, head: 'wrap', wrap: 0x1e301e, wrapTrim: 0x121d12, beard: 'long', staff: 'planted', ry: 0.35, s: 1.14 });
    person(W, group, [4.5, 0, 6], { robe: 0x8a6a44, head: 'wrap', wrap: 0x1e301e, wrapTrim: 0x121d12, beard: 'long', staff: 'planted', ry: -0.18, s: 1.14 });
    person(W, group, [1, 0, -5], { robe: 0x8a6a44, head: 'wrap', wrap: 0x1e301e, wrapTrim: 0x121d12, beard: 'long', staff: 'planted', ry: -0.08, s: 1.11 });

    return W.finish();
}

export default { build };
